{
  "@context": "https://schema.org",
  "@type": "ItemList",
  "name": "How to use Citi® Flex Pay for travel",
  "itemListOrder": "https://schema.org/ItemListUnordered",
  "numberOfItems": 4,
  "itemListElement": [{
    "@type": "ListItem",
    "position": 1,
    "item": {
      "@type": "Thing",
      "name": "Book your travel",
      "description": "Start by booking your trip using your eligible Citi credit card. You can book:
• Flights
• Hotels
• Car rentals
• Activities and experiences
You can also explore Citi Travel®, where you can reserve travel and earn or redeem ThankYou® Points while enjoying competitive pricing on hotels and customer service is available 24/7."
    }
  },{
    "@type": "ListItem",
    "position": 2,
    "item": {
      "@type": "Thing",
      "name": "Select eligible purchases",
      "description": "Once your purchase posts to your account, look for transactions of $75 or more that are eligible for Citi® Flex Pay.
Another way to pay is through the Citi Travel website. Eligible Citi Travel customers are offered Flex Pay at checkout while making a purchase of $75 or more and can enroll with just one click."
    }
  },{
    "@type": "ListItem",
    "position": 3,
    "item": {
      "@type": "Thing",
      "name": "Choose your plan",
      "description": "Select the purchase and review your options. You’ll see:
 
• Your fixed monthly payment
• The length of your plan
• Your total Plan Fee. This gives you a clear view of your payment plan before confirming.
• Finalize your card payment details, then view and accept the cancellation policy.
• Lastly you will need to select Citi Flex Pay. 
• For easy enrollment Citi Travel customers are eligible for 1-click enrollment. 
• With a single click during check out customers can select the box next to ”Buy now, pay later with Citi Flex Pay on your card” and the purchase will be automatically enrolled in a 12-month payment plan with $0 fees and no interest."
    }
  },{
    "@type": "ListItem",
    "position": 4,
    "item": {
      "@type": "Thing",
      "name": "Pay over time",
      "description": "After enrolling, your monthly Flex Pay amount is added to your minimum payment due each billing cycle until the balance is paid off."
    }
  }]
}

{
  "@context": "https://schema.org",
  "@type": "ItemList",
  "name": "Citi Travel®",
  "itemListOrder": "https://schema.org/ItemListUnordered",
  "numberOfItems": 2,
  "itemListElement": [{
    "@type": "ListItem",
    "position": 1,
    "item": {
      "@type": "Thing",
      "name": "Why use Citi® Flex Pay for travel?",
      "description": "Citi® Flex helps to offer a simple way to manage travel expenses while still enjoying the benefits of your credit card. By using it, you can take advantage of:
 
• Flexible payments: Spread out larger costs into fixed monthly amounts
• Clear structure: Know your payment amount and timeline upfront
• Reward opportunities: Continue earning ThankYou® points on eligible purchases
• Seamless experience: Payments are added to your minimum monthly payment"
    }
  },{
    "@type": "ListItem",
    "position": 2,
    "item": {
      "@type": "Thing",
      "name": "Using Citi® Flex Pay for your travel",
      "description": "Citi® Flex Pay offers flexibility by allowing you to break down larger eligible travel purchases into predictable monthly payments. When combined with tools like the Citi Travel® website and the benefits of Citi® credit cards, it helps to create a well-rounded approach to planning, booking and enjoying your travel experience."
    }
  }]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [{
    "@type": "Question",
    "name": "What is Citi® Flex Pay?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Citi® Flex Pay is a benefit available on eligible Citi credit cards that allows you to break-up eligible purchases of $75 or more into fixed, monthly payments over a set period of time.
Instead of paying for your entire trip upfront, you can:
 
• Choose a payment plan that fits your budget
• Make equal monthly payments
• Pay a fixed monthly Plan Fee instead of interest
Your Flex Pay payment is automatically included in your minimum payment due each billing cycle, so everything stays streamlined."
    }
  }]
